('8b575ead-b3e2-5b46-b9a0-76e03eea0509'::uuid,'est2','"Triangles, Trigonometry & Similarity"'::jsonb,'medium','mcq','"If 0° ≤ x ≤ 90° and tan x = 15/8, then cos x = ?"'::jsonb,'[{"key":"A","text":"8/17"},{"key":"B","text":"15/17"},{"key":"C","text":"17/8"},{"key":"D","text":"17/15"},{"key":"E","text":"8/15"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-39","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Triangles, Trigonometry & Similarity"}'::jsonb,'"A"'::jsonb,'"Source-keyed answer from pt2.md (P2-39)."'::jsonb),
('573ee37e-a5da-5539-b517-d99337a3ab9a'::uuid,'est2','"Coordinate Geometry, Circles & Conics"'::jsonb,'medium','mcq','"A square pool with an area of 81 square feet is to be placed entirely within a circular enclosure with a radius of 10 feet. Tiles will be laid within the entire enclosure around the pool (but not under it). What is the approximate area, in square feet, of the enclosure that will be tiled?"'::jsonb,'[{"key":"F","text":"81"},{"key":"G","text":"233"},{"key":"H","text":"315"},{"key":"J","text":"396"},{"key":"K","text":"Cannot be determined without knowing the exact placement of the pool."}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-40","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Coordinate Geometry, Circles & Conics"}'::jsonb,'"G"'::jsonb,'"Source-keyed answer from pt2.md (P2-40)."'::jsonb),
('c373d452-68d4-535a-b859-82ddf81b0302'::uuid,'est2','"Coordinate Geometry, Circles & Conics"'::jsonb,'medium','mcq','"In the standard (x, y) coordinate plane, which of the following lines goes through (3, 4) and is parallel to y = 2x + 2?"'::jsonb,'[{"key":"A","text":"y = (1/2)x + 2"},{"key":"B","text":"y = 2x − 2"},{"key":"C","text":"y = 2x + 4"},{"key":"D","text":"y = 2x + 10"},{"key":"E","text":"y = 3x + 2"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-41","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Coordinate Geometry, Circles & Conics"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from pt2.md (P2-41)."'::jsonb),
('a986851a-49c9-58d2-aa53-68699e094b3b'::uuid,'est2','"Triangles, Trigonometry & Similarity"'::jsonb,'medium','mcq','"In the figure below, tan φ = ?\n[Figure: Coordinate plane with a ray from the origin through the point (3, 3); φ is the angle between the positive x-axis and the ray.]"'::jsonb,'[{"key":"F","text":"1/√2"},{"key":"G","text":"√2"},{"key":"H","text":"1"},{"key":"J","text":"3"},{"key":"K","text":"3√2"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-42","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Triangles, Trigonometry & Similarity","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/P2-42.png","image_alt":"Original graph, diagram, or table for P2-42","visual_verified":true}'::jsonb,'"H"'::jsonb,'"Source-keyed answer from pt2.md (P2-42)."'::jsonb),
('43e3a396-e2cc-5af3-918a-8d2d5568848c'::uuid,'est2','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','mcq','"Which of the following operations will produce the smallest result when substituted for the blank in the expression: (2/3) ____ − 3?"'::jsonb,'[{"key":"A","text":"plus"},{"key":"B","text":"minus"},{"key":"C","text":"multiplied by"},{"key":"D","text":"divided by"},{"key":"E","text":"averaged with"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-43","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"A"'::jsonb,'"Source-keyed answer from pt2.md (P2-43)."'::jsonb),
('c73ca137-c492-5ed4-882b-1044bac31503'::uuid,'est2','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','mcq','"The value of b that will make (b/3) + 2 = 1/4 a true statement lies between which of the following numbers?"'::jsonb,'[{"key":"F","text":"−4 and −6"},{"key":"G","text":"−1 and −3"},{"key":"H","text":"−1 and 1"},{"key":"J","text":"1 and 3"},{"key":"K","text":"3 and 5"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-44","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"F"'::jsonb,'"Source-keyed answer from pt2.md (P2-44)."'::jsonb),
('2af4953b-c463-54c4-b837-7dc59bbdab83'::uuid,'est2','"Sequences, Complex Numbers & Advanced Algebra"'::jsonb,'medium','mcq','"What is the solution set of |3a − 2| ≤ 7?"'::jsonb,'[{"key":"A","text":"{a: a ≤ 3}"},{"key":"B","text":"{a: −5/3 ≤ a ≤ 3}"},{"key":"C","text":"{a: −5/3 ≥ a ≥ 3}"},{"key":"D","text":"{a: −5/3 ≤ a ≥ 3}"},{"key":"E","text":"{a: −5/3 ≥ a ≤ 3}"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-45","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Sequences, Complex Numbers & Advanced Algebra"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from pt2.md (P2-45)."'::jsonb),
('46aec849-8898-5805-be3d-b693a5d30846'::uuid,'est2','"Triangles, Trigonometry & Similarity"'::jsonb,'medium','mcq','"When measured from a point on the ground that is a certain distance from the base of a cell phone tower, the angle of elevation to the top of the tower is 41°, as shown below. The height of the cell phone tower is 200 feet. What is the distance, in feet, to the cell phone tower?\n[Figure: Right triangle; vertical leg 200 ft (tower); angle of elevation 41° at the ground point; horizontal leg labeled Distance (?).]"'::jsonb,'[{"key":"F","text":"200 tan 41°"},{"key":"G","text":"200 sin 41°"},{"key":"H","text":"200 cos 41°"},{"key":"J","text":"200 sec 41°"},{"key":"K","text":"200 cot 41°"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-46","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Triangles, Trigonometry & Similarity","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/P2-46.png","image_alt":"Original graph, diagram, or table for P2-46","visual_verified":true}'::jsonb,'"K"'::jsonb,'"Source-keyed answer from pt2.md (P2-46)."'::jsonb),
('e3ad0c4c-52f5-5ded-af46-f291a8dd4ee9'::uuid,'est2','"Plane Geometry, Measurement & Transformations"'::jsonb,'medium','mcq','"For the area of a square to triple, the new side lengths must be the length of the old sides multiplied by:"'::jsonb,'[{"key":"A","text":"√3"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"2√3"},{"key":"E","text":"9"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-47","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Plane Geometry, Measurement & Transformations"}'::jsonb,'"A"'::jsonb,'"Source-keyed answer from pt2.md (P2-47)."'::jsonb),
('c2cc5115-41dd-5da9-9380-7ddbe91a272a'::uuid,'est2','"Solid Geometry & Volume"'::jsonb,'medium','mcq','"The volume of a cube is given by the formula s³, where s is the length of a side. If a cube has a volume of 64, and the length of each side is halved, the new cube''s volume will be:"'::jsonb,'[{"key":"F","text":"3"},{"key":"G","text":"6"},{"key":"H","text":"8"},{"key":"J","text":"16"},{"key":"K","text":"32"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-48","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Solid Geometry & Volume"}'::jsonb,'"H"'::jsonb,'"Source-keyed answer from pt2.md (P2-48)."'::jsonb),
('11c5998f-7525-5ac3-b622-ac8749e32b10'::uuid,'est2','"Plane Geometry, Measurement & Transformations"'::jsonb,'medium','mcq','"In the parallelogram below, lengths are given in inches. What is the area of the parallelogram, in square inches?\n[Figure: Parallelogram with top and bottom sides 7; slant sides √47; overall height 9 indicated by a vertical bracket on the left.]"'::jsonb,'[{"key":"A","text":"√94"},{"key":"B","text":"7√47"},{"key":"C","text":"49"},{"key":"D","text":"63"},{"key":"E","text":"16√47"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-49","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Plane Geometry, Measurement & Transformations","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/P2-49.png","image_alt":"Original graph, diagram, or table for P2-49","visual_verified":true}'::jsonb,'"D"'::jsonb,'"Source-keyed answer from pt2.md (P2-49)."'::jsonb),
('d9087c98-5c16-572e-91ff-e1f3275ce000'::uuid,'est2','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','mcq','"If 8a⁶b³ < 0, then which of the following CANNOT be true?"'::jsonb,'[{"key":"F","text":"b < 0"},{"key":"G","text":"b > 0"},{"key":"H","text":"a = b"},{"key":"J","text":"a < 0"},{"key":"K","text":"a > 0"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-50","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"G"'::jsonb,'"Source-keyed answer from pt2.md (P2-50)."'::jsonb),
('d4601d40-3893-5b07-93fa-254da30f98b6'::uuid,'est2','"Rational, Radical, Exponential & Logarithmic Functions"'::jsonb,'hard','mcq','"If log₄ x = 3, then x = ?"'::jsonb,'[{"key":"A","text":"1/log 12"},{"key":"B","text":"4 log 3"},{"key":"C","text":"12"},{"key":"D","text":"64"},{"key":"E","text":"81"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-51","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Rational, Radical, Exponential & Logarithmic Functions"}'::jsonb,'"D"'::jsonb,'"Source-keyed answer from pt2.md (P2-51)."'::jsonb),
('00f7604c-84ea-5cc8-8a76-b52ea17ab975'::uuid,'est2','"Functions, Transformations & Graphs"'::jsonb,'medium','mcq','"If a system of 2 linear equations in 2 variables has NO solution, and 1 of the equations is graphed in the (x, y) coordinate plane below, which of the following could be the equation of the other line?\n[Figure: Line through (3, 0) and (0, −4).]"'::jsonb,'[{"key":"F","text":"y = −2"},{"key":"G","text":"y = −(1/4)x + 2"},{"key":"H","text":"y = −2x − 4"},{"key":"J","text":"y = (4/3)x + 2"},{"key":"K","text":"y = 4x − 4"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-52","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Functions, Transformations & Graphs","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/P2-52.png","image_alt":"Original graph, diagram, or table for P2-52","visual_verified":true}'::jsonb,'"J"'::jsonb,'"Source-keyed answer from pt2.md (P2-52)."'::jsonb),
('ab8a338c-19c9-5dae-8433-9157bfe6abaf'::uuid,'est2','"Statistics, Probability & Data Analysis"'::jsonb,'hard','mcq','"In a game, 80 marbles numbered 00 through 79 are placed in a box. A player draws 1 marble at random from the box. Without replacing the first marble, the player draws a second marble at random. If both marbles drawn have the same ones digit (that is, both marbles have a number ending in 0, 1, 2, 3, etc.), the player is a winner. If the first marble drawn is numbered 35, what is the probability that the player will be a winner on the next draw?"'::jsonb,'[{"key":"A","text":"1/79"},{"key":"B","text":"7/80"},{"key":"C","text":"7/79"},{"key":"D","text":"1/10"},{"key":"E","text":"8/79"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-53","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"C"'::jsonb,'"Source-keyed answer from pt2.md (P2-53)."'::jsonb),
('115c1f9c-15ca-5ed5-b981-8bedbdb193e1'::uuid,'est2','"Coordinate Geometry, Circles & Conics"'::jsonb,'medium','mcq','"In the standard (x, y) coordinate plane, what is the equation of the line that passes through the origin and the point (3, 4)?"'::jsonb,'[{"key":"F","text":"y = (1/4)x + 3/4"},{"key":"G","text":"y = (1/4)x − 1/3"},{"key":"H","text":"y = (4/3)x"},{"key":"J","text":"y = (1/2)x + 3/4"},{"key":"K","text":"y = (9/4)x"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-54","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Coordinate Geometry, Circles & Conics"}'::jsonb,'"H"'::jsonb,'"Source-keyed answer from pt2.md (P2-54)."'::jsonb),
('10448878-0e80-5f0e-aa3d-6e71a155345d'::uuid,'est2','"Triangles, Trigonometry & Similarity"'::jsonb,'medium','mcq','"The measure of the vertex angle of an isosceles triangle is (a + 30)°. The base angles each measure (2a − 15)°. What is the measure in degrees of one of the base angles?"'::jsonb,'[{"key":"A","text":"36°"},{"key":"B","text":"45°"},{"key":"C","text":"57°"},{"key":"D","text":"66°"},{"key":"E","text":"90°"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-55","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Triangles, Trigonometry & Similarity"}'::jsonb,'"C"'::jsonb,'"Source-keyed answer from pt2.md (P2-55)."'::jsonb),
